#!/usr/bin/env python3
"""Generate a responsive, dependency-free local landing page from the manifest."""
from __future__ import annotations
import html,json
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]
def main():
 d=json.loads((ROOT/'results/census.json').read_text());cards=[]
 for rank,v in d['ranks'].items():
  cards.append(f'''<article class="rank"><div class="rank-top"><span>RANK {rank}</span><span class="pill">COMPLETE</span></div><h2>{v['bound']:,}<small>multiplicity bound</small></h2><p class="count">{v['classes']:,} distinct based rings</p><div class="links"><a href="../manuscripts/rank{rank}.pdf">Read the manuscript ↗</a><a href="../{html.escape(v['tables'])}">Full tensor data · gzip</a><a href="../results/rank{rank}_counts.csv">Exact-multiplicity counts</a></div></article>''')
 page='''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="description" content="Exact whole-rank fusion-ring censuses, mathematical companions and independent verification."><title>Fusion Ring Census</title><style>
:root{--ink:#143044;--teal:#0c766f;--muted:#526472;--line:#d9e4e7;--paper:#f5f8f9;--white:#fff}*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;background:var(--paper);color:var(--ink);font:16px/1.65 system-ui,-apple-system,"Segoe UI",sans-serif}a{color:var(--teal);text-underline-offset:4px}a:hover{color:#103e59}a:focus-visible{outline:3px solid #b99d38;outline-offset:4px}.wrap{max-width:1180px;margin:auto;padding:0 32px}header{background:var(--white);border-bottom:1px solid var(--line)}nav{display:flex;justify-content:space-between;gap:20px;align-items:center;padding:20px 0}.brand{font-size:15px;font-weight:750;letter-spacing:.12em;color:var(--ink);text-decoration:none}nav .navlinks{display:flex;flex-wrap:wrap;gap:24px;font-size:14px}nav a{text-decoration:none}main{padding-bottom:52px}.hero{padding:76px 0 58px;display:grid;grid-template-columns:1fr 260px;gap:50px;align-items:start}.eyebrow{color:var(--teal);letter-spacing:.18em;font-size:12px;font-weight:750}h1{font-size:clamp(40px,5.2vw,68px);line-height:1.08;letter-spacing:-.04em;margin:22px 0}h1 span{color:var(--teal)}.lead{font-size:19px;max-width:670px;color:var(--muted)}.stat{border-left:3px solid var(--teal);padding:13px 0 13px 22px;margin-top:65px}.stat strong{display:block;font-size:34px;letter-spacing:-.035em}.stat span{font-size:14px;color:var(--muted)}.notice{border:1px solid var(--line);background:white;border-left:4px solid var(--teal);padding:18px 23px;font-size:15px;margin-bottom:36px}.sectionhead{display:flex;justify-content:space-between;align-items:end;gap:24px;margin:35px 0 20px}.sectionhead h2{margin:0;font-size:25px;letter-spacing:-.025em}.sectionhead p{margin:0;color:var(--muted);font-size:14px}.grid{display:grid;grid-template-columns:repeat(3,1fr);gap:20px}.rank{background:white;border:1px solid var(--line);border-radius:10px;padding:26px;box-shadow:0 3px 10px #15394c05}.rank-top{display:flex;align-items:center;justify-content:space-between;gap:10px;font-size:12px;letter-spacing:.14em;font-weight:700}.pill{font-size:9px;letter-spacing:.08em;color:var(--teal);background:#e8f3f1;border-radius:4px;padding:3px 7px}.rank h2{font-size:46px;line-height:1.1;margin:29px 0 16px;letter-spacing:-.04em}.rank h2 small{display:block;font-size:13px;font-weight:400;color:var(--muted);letter-spacing:0;margin-top:9px}.count{border-bottom:1px solid var(--line);padding-bottom:19px;font-size:14px}.links{display:grid;gap:8px;font-size:13px}.links a{text-decoration:none}.panel{display:grid;grid-template-columns:1fr 1fr;gap:30px;margin-top:52px;padding-top:32px;border-top:1px solid var(--line)}.panel h2{font-size:25px;line-height:1.25;letter-spacing:-.02em}.panel p{color:var(--muted)}pre{overflow:auto;background:var(--ink);color:#e8f4f4;padding:22px;border-radius:8px;font-size:12px;line-height:1.8}code{font-family:ui-monospace,SFMono-Regular,Consolas,monospace}.small{font-size:13px;color:var(--muted)}footer{border-top:1px solid var(--line);padding:26px 0;color:var(--muted);font-size:12px}.foot{display:flex;justify-content:space-between;gap:20px;flex-wrap:wrap}@media(max-width:840px){.hero{grid-template-columns:1fr;padding:45px 0 30px;gap:20px}.stat{margin-top:0}.grid{grid-template-columns:repeat(2,1fr)}.panel{grid-template-columns:1fr}.sectionhead{display:block}.sectionhead p{margin-top:8px}}@media(max-width:520px){.wrap{padding:0 20px}.grid{grid-template-columns:1fr}nav{align-items:start;flex-direction:column}.hero h1{font-size:43px}.rank{padding:23px}}
</style></head><body><header><div class="wrap"><nav aria-label="Main navigation"><a class="brand" href="#">FUSION RING CENSUS</a><div class="navlinks"><a href="#coverage">Data</a><a href="../manuscripts/README.md">Manuscripts</a><a href="../oeis/README.md">OEIS</a><a href="REPRODUCIBILITY.md">Reproduce</a></div></nav></div></header><main class="wrap"><section class="hero"><div><div class="eyebrow">EXACT ENUMERATION / MATHEMATICS / OPEN VERIFICATION</div><h1>Every ring in scope.<br><span>Every claim traceable.</span></h1><p class="lead">Complete bounded censuses of based fusion rings at ranks three through eight—with full multiplication tensors, mathematical companions and independent integer verification.</p></div><aside class="stat"><strong>@@TOTAL@@</strong><span>distinct rings in the released datasets</span><strong>6</strong><span>standalone mathematical companions</span></aside></section><div class="notice"><strong>Complete whole-rank results only.</strong> Every duality type is included. An interrupted search cannot become a new census term. These are classifications of based rings, not of fusion categories.</div><section id="coverage"><div class="sectionhead"><h2>Explore the certified coverage</h2><p>Counts are cumulative through the displayed multiplicity bound.</p></div><div class="grid">@@CARDS@@</div></section><section class="panel"><div><div class="eyebrow">REPRODUCIBLE BY DESIGN</div><h2>Read the argument.<br>Check the tensors.</h2><p>Each companion distinguishes an exhaustive-search argument from verification of its outputs. Singular systems and noncommutative cases stay inside the search. Original execution records are preserved separately from fresh regression tests.</p><p><a href="../methods/completeness.md">Completeness arguments ↗</a><br><a href="../verification/repository_checks/full_release.json">Fresh full-release verification ↗</a><br><a href="PROVENANCE.md">Source audit and provenance ↗</a></p></div><div><pre><code># Verify all released rings, not a sample\npython3 scripts/check_release.py --full\n\n# Extend a whole rank under one deadline\npython3 scripts/extend_census.py \\\n  --rank 6 --seconds 4200 --threads "$(nproc)" \\\n  --out runs/rank6-frontier</code></pre><p class="small">Python + C++17/OpenMP. No SageMath, Mathematica or third-party Python package. Rank three stops at multiplicity 1000.</p></div></section><section class="panel"><div><div class="eyebrow">OEIS WORKSPACE</div><h2>One census. Both directions.</h2><p>Fixed-rank and fixed-multiplicity projections are generated from the same complete manifest. The rank-five correction includes explicit deletion certificates; larger incomplete searches never supply sequence terms.</p><p><a href="../oeis/README.md">Open the OEIS folder ↗</a></p></div><div><div class="eyebrow">PUBLICATION STATUS</div><h2>Published privately.<br>Verified candidates require review.</h2><p>The repository is private. The manual long campaign covers ranks 5–8 with 70 driver minutes and 75 job minutes per rank, retaining artifacts for 14 days. The released numerical counts remain unchanged.</p><p><a href="RELEASES.md">Publication and release procedure ↗</a></p></div></section></main><footer><div class="wrap foot"><span>Sébastien Palcoux · Computational research companion · September 2026</span><span><a href="../CITATION.cff">Cite</a> · <a href="../NOTICE.md">Attribution</a> · <a href="../CONTRIBUTING.md">Contribute</a></span></div></footer></body></html>'''
 page=page.replace('@@TOTAL@@',f"{d['total_classes']:,}").replace('@@CARDS@@',''.join(cards))
 target=ROOT/'docs/index.html';target.write_text(page);print(target)
if __name__=='__main__':main()
